        Linear interpolation of one-dimensional data
        :param x: The x-coordinate of the data point, list.
        :param y: The y-coordinate of the data point, list.
        :param x_interp: The x-coordinate of the interpolation point, list.
        :return: The y-coordinate of the interpolation point, list.
        >>> interpolation = Interpolation()
        >>> interpolation.interpolate_1d([1, 2, 3], [1, 2, 3], [1.5, 2.5])
        [1.5, 2.5]

        """
        if not x or not y or not x_interp:
            return []

        if len(x) != len(y):
            raise ValueError("x and y must have the same length")

        if len(x) < 2:
            raise ValueError("Need at least 2 data points for interpolation")

        result = []

        for xi in x_interp:
            # Find the two points that bracket xi
            if xi <= x[0]:
                # Extrapolate using first two points
                x1, x2 = x[0], x[1]
                y1, y2 = y[0], y[1]
            elif xi >= x[-1]:
                # Extrapolate using last two points
                x1, x2 = x[-2], x[-1]
                y1, y2 = y[-2], y[-1]
            else:
                # Find bracketing points
                for i in range(len(x) - 1):
                    if x[i] <= xi <= x[i + 1]:
                        x1, x2 = x[i], x[i + 1]
                        y1, y2 = y[i], y[i + 1]
                        break

            # Linear interpolation formula: y = y1 + (y2 - y1) * (x - x1) / (x2 - x1)
            if x2 == x1:
                yi = y1
            else:
                yi = y1 + (y2 - y1) * (xi - x1) / (x2 - x1)

            result.append(yi)

        return result

    @staticmethod
    def interpolate_2d(x, y, z, x_interp, y_interp):
        """
        Linear interpolation of two-dimensional data
        :param x: The x-coordinate of the data point, list.
        :param y: The y-coordinate of the data point, list.
        :param z: The z-coordinate of the data point, list.
        :param x_interp: The x-coordinate of the interpolation point, list.
        :param y_interp: The y-coordinate of the interpolation point, list.
        :return: The z-coordinate of the interpolation point, list.
        >>> interpolation = Interpolation()
        >>> interpolation.interpolate_2d([1, 2, 3], [1, 2, 3], [[1, 2, 3], [4, 5, 6], [7, 8, 9]], [1.5, 2.5], [1.5, 2.5])
        [3.0, 7.0]

        """
        if not x or not y or not z or not x_interp or not y_interp:
            return []

        if len(x) != len(z) or len(y) != len(z[0]):
            raise ValueError("Dimensions of x, y, and z must be consistent")

        if len(x_interp) != len(y_interp):
            raise ValueError("x_interp and y_interp must have the same length")

        result = []

        for xi, yi in zip(x_interp, y_interp):
            # Find the four corner points for bilinear interpolation

            # Find x indices
            if xi <= x[0]:
                x_idx1, x_idx2 = 0, 1
            elif xi >= x[-1]:
                x_idx1, x_idx2 = len(x) - 2, len(x) - 1
            else:
