        :param binary_num: str, binary number
        :return: int, the decimal representation of binary number str.
        >>> NumberConverter.binary_to_decimal('1010010110110111')
        42423
        """
        if binary_num is None:
            raise ValueError("Input cannot be None")
        if not isinstance(binary_num, str):
            raise TypeError("Input must be a string")
        if not binary_num:
            raise ValueError("Input cannot be empty")
        if not all(c in '01' for c in binary_num):
            raise ValueError("Input must contain only binary digits (0 and 1)")

        decimal = 0
        power = 0
        for digit in reversed(binary_num):
            decimal += int(digit) * (2 ** power)
            power += 1
        return decimal

    @staticmethod
    def decimal_to_octal(decimal_num):
        """
        Convert a number from decimal format to octal format.
        :param decimal_num: int, decimal number
        :return: str, the octal representation of an integer.
        >>> NumberConverter.decimal_to_octal(42423)
        '122667'
        """
        if decimal_num is None:
            raise ValueError("Input cannot be None")
        if not isinstance(decimal_num, int):
            raise TypeError("Input must be an integer")
        if decimal_num < 0:
            raise ValueError("Input must be non-negative")
        if decimal_num == 0:
            return '0'

        octal = ''
        while decimal_num > 0:
            octal = str(decimal_num % 8) + octal
            decimal_num //= 8
        return octal

    @staticmethod
    def octal_to_decimal(octal_num):
        """
        Convert a number from octal format to decimal format.
        :param octal_num: str, octal num
        :return: int, the decimal representation of octal number str.
        >>> NumberConverter.octal_to_decimal('122667')
        42423
        """
        if octal_num is None:
            raise ValueError("Input cannot be None")
        if not isinstance(octal_num, str):
            raise TypeError("Input must be a string")
        if not octal_num:
            raise ValueError("Input cannot be empty")
        if not all(c in '01234567' for c in octal_num):
            raise ValueError("Input must contain only octal digits (0-7)")

        decimal = 0
        power = 0
        for digit in reversed(octal_num):
            decimal += int(digit) * (8 ** power)
            power += 1
        return decimal

    @staticmethod
    def decimal_to_hex(decimal_num):
        """
        Convert a number from decimal format to hex format.
        :param decimal_num: int, decimal number
        :return hex_num: str, the hex representation of an integer.
        >>> NumberConverter.decimal_to_hex(42423)
        'a5b7'
        """
        if decimal_num is None:
            raise ValueError("Input cannot be None")
        if not isinstance(decimal_num, int):
            raise TypeError("Input must be an integer")
        if decimal_num < 0:
            raise ValueError("Input must be non-negative")
        if decimal_num == 0:
            return '0'

        hex_digits = '0123456789abcdef'
        hex_num = ''
        while decimal_num > 0:
            hex_num = hex_digits[decimal_num % 16] + hex_num
            decimal_num //= 16
        return hex_num

    @staticmethod
    def hex_to_decimal(hex_num):
        """
        Convert a number from hex format to decimal format.
        :param hex_num: str, hex num
        :return: int, the decimal representation of hex number str.
        >>> NumberConverter.hex_to_decimal('a5b7')
        42423
        """
        if hex_num is None:
            raise ValueError("Input cannot be None")
        if not isinstance(hex_num, str):
            raise TypeError("Input must be a string")
        if not hex_num:
            raise ValueError("Input cannot be empty")

        hex_num = hex_num.lower()
        if not all(c in '0123456789abcdef' for c in hex_num):
            raise ValueError("Input must contain only hexadecimal digits (0-9, a-f)")

        decimal = 0
        power = 0
        for digit in reversed(hex_num):
            if digit.isdigit():
                digit_value = int(digit)
            else:
                digit_value = ord(digit) - ord('a') + 10
            decimal += digit_value * (16 ** power)
            power += 1
        return decimal

class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    def __init__(self):
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        """
        if string is None:
            return None

        if not string:
            return string

        result = []
        i = 0

        while i < len(string):
            if i < len(string) - 2 and string[i:i+2] == '&#':
                # Find the end of the entity
                end_pos = string.find(';', i + 2)
                if end_pos != -1:
                    entity_content = string[i+2:end_pos]

                    try:
                        if entity_content.startswith('x') or entity_content.startswith('X'):
                            # Hexadecimal entity
                            if len(entity_content) > 1:
                                hex_part = entity_content[1:]
                                if all(self.is_hex_char(c) for c in hex_part):
                                    char_code = int(hex_part, 16)
                                    result.append(chr(char_code))
                                    i = end_pos + 1
                                    continue
                        else:
                            # Decimal entity
                            if entity_content.isdigit():
                                char_code = int(entity_content)
                                result.append(chr(char_code))
                                i = end_pos + 1
                                continue
                    except (ValueError, OverflowError):
                        pass

            result.append(string[i])
            i += 1

        return ''.join(result)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True

        """
        if char is None or len(char) != 1:
            return False

        return char in '0123456789abcdefABCDEF'

import numpy as np
from gensim import matutils
from numpy import dot, array
import math

class VectorUtil:
    """
    The class provides vector operations, including calculating similarity, cosine similarities, average similarity, and IDF weights.
    """

    @staticmethod
    def similarity(vector_1, vector_2):
        """
        Compute the cosine similarity between one vector and another vector.
        :param vector_1: numpy.ndarray, Vector from which similarities are to be computed, expected shape (dim,).
        :param vector_2: numpy.ndarray, Vector from which similarities are to be computed, expected shape (dim,).
        :return: numpy.ndarray, Contains cosine distance between `vector_1` and `vector_2`
        >>> vector_1 = np.array([1, 1])
        >>> vector_2 = np.array([1, 0])
        >>> VectorUtil.similarity(vector_1, vector_2)
        0.7071067811865475
        """
        if vector_1 is None or vector_2 is None:
            return 0.0

        vector_1 = np.array(vector_1)
        vector_2 = np.array(vector_2)

        if len(vector_1) == 0 or len(vector_2) == 0:
            return 0.0

        norm_1 = np.linalg.norm(vector_1)
        norm_2 = np.linalg.norm(vector_2)

        if norm_1 == 0 or norm_2 == 0:
            return 0.0

        return dot(vector_1, vector_2) / (norm_1 * norm_2)

    @staticmethod
    def cosine_similarities(vector_1, vectors_all):
        """
        Compute cosine similarities between one vector and a set of other vectors.
        :param vector_1: numpy.ndarray, Vector from which similarities are to be computed, expected shape (dim,).
        :param vectors_all: list of numpy.ndarray, For each row in vectors_all, distance from vector_1 is computed, expected shape (num_vectors, dim).
        :return: numpy.ndarray, Contains cosine distance between `vector_1` and each row in `vectors_all`, shape (num_vectors,).
        >>> vector1 = np.array([1, 2, 3])
        >>> vectors_all = [np.array([4, 5, 6]), np.array([7, 8, 9])]
        >>> VectorUtil.cosine_similarities(vector1, vectors_all)
        [0.97463185 0.95941195]
        """
        if vector_1 is None or vectors_all is None or len(vectors_all) == 0:
            return np.array([])

        vector_1 = np.array(vector_1)

        if len(vector_1) == 0:
            return np.array([0.0] * len(vectors_all))

        similarities = []
        for vector in vectors_all:
            sim = VectorUtil.similarity(vector_1, vector)
            similarities.append(sim)

        return np.array(similarities)

    @staticmethod
    def n_similarity(vector_list_1, vector_list_2):
        """
        Compute cosine similarity between two sets of vectors.
        :param vector_list_1: list of numpy vector
        :param vector_list_2: list of numpy vector
        :return: numpy.ndarray, Similarities between vector_list_1 and vector_list_2.
        >>> vector_list1 = [np.array([1, 2, 3]), np.array([4, 5, 6])]
        >>> vector_list2 = [np.array([7, 8, 9]), np.array([10, 11, 12])]
        >>> VectorUtil.n_similarity(vector_list1, vector_list2)
        0.9897287473881233
        """
        if vector_list_1 is None or vector_list_2 is None or len(vector_list_1) == 0 or len(vector_list_2) == 0:
            return 0.0

        # Compute mean vectors for each list
        mean_vector_1 = np.mean([np.array(v) for v in vector_list_1], axis=0)
        mean_vector_2 = np.mean([np.array(v) for v in vector_list_2], axis=0)

        return VectorUtil.similarity(mean_vector_1, mean_vector_2)

    @staticmethod
    def compute_idf_weight_dict(total_num, number_dict):
        """
        Calculate log(total_num+1/count+1) for each count in number_dict
        :param total_num: int
        :param number_dict: dict
        :return: dict
        >>> num_dict = {'key1':0.1, 'key2':0.5}
        >>> VectorUtil.compute_idf_weight_dict(2, num_dict)
        {'key1': 1.0033021088637848, 'key2': 0.6931471805599453}
        """
        if number_dict is None:
            return {}

        result = {}
        for key, count in number_dict.items():
            result[key] = math.log((total_num + 1) / (count + 1))

        return result

class Words2Numbers:
    """
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    """

    def __init__(self):
        """
        Initialize the word lists and dictionaries required for conversion
        """
        self.numwords = {}
        self.units = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        ]
        self.tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.scales = ["hundred", "thousand", "million", "billion", "trillion"]

        self.numwords["and"] = (1, 0)
        for idx, word in enumerate(self.units):
            self.numwords[word] = (1, idx)
        for idx, word in enumerate(self.tens):
            self.numwords[word] = (1, idx * 10)
        for idx, word in enumerate(self.scales):
            self.numwords[word] = (10 ** (idx * 3 or 2), 0)

        self.ordinal_words = {'first': 1, 'second': 2, 'third': 3, 'fifth': 5, 'eighth': 8, 'ninth': 9, 'twelfth': 12}
        self.ordinal_endings = [('ieth', 'y'), ('th', '')]

    def text2int(self, textnum):
        """
        Convert the word string to the corresponding integer string
        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        """
        if not textnum or textnum is None:
            return "0"

        textnum = textnum.strip().lower()
        if not textnum:
            return "0"

        # Handle ordinal words
        if textnum in self.ordinal_words:
            return str(self.ordinal_words[textnum])

        # Handle ordinal endings
        for ending, replacement in self.ordinal_endings:
            if textnum.endswith(ending):
                base_word = textnum[:-len(ending)] + replacement
                if base_word in self.numwords:
                    return str(self.numwords[base_word][1])

        # Replace hyphens with spaces and split
        words = textnum.replace('-', ' ').split()

        current = result = 0

        for word in words:
            if word not in self.numwords:
                continue

            scale, increment = self.numwords[word]

            if scale > 1:
                if scale > 100:
                    result += current
                    current = 0
                current = (current or 1) * scale
            else:
                current += increment

        result += current
        return str(result)

    def is_valid_input(self, textnum):
        """
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: True if input is valid, False otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        False
        """
        if not textnum or textnum is None:
            return False

        textnum = textnum.strip().lower()
        if not textnum:
            return False

        # Check if it's an ordinal word
        if textnum in self.ordinal_words:
            return True

        # Check ordinal endings
        for ending, replacement in self.ordinal_endings:
            if textnum.endswith(ending):
                base_word = textnum[:-len(ending)] + replacement
                if base_word in self.numwords:
                    return True

        # Replace hyphens with spaces and split
        words = textnum.replace('-', ' ').split()

        # Check if all words are valid number words
        for word in words:
            if word not in self.numwords:
                return False

        return True
